using UnityEngine;
using UnityEditor;
using UnityEngine.InputSystem;
using UnityEngine.InputSystem.LowLevel;
using System;
using System.IO;
using System.Text;
using System.Collections.Generic;
using ConRoi.Investigation.V36.R107;

namespace Unity.AI.Assistant.Agent.Dynamic.Extension.Editor
{
    internal class CommandScript : IRunCommand
    {
        public void Execute(ExecutionResult r)
        {
            var s = UnityEngine.Object.FindFirstObjectByType<InvestigationSession>();
            if (!s.SavePath.Contains("NavFixture_a789222") || !s.Has("letter"))
                throw new Exception("Isolated navigation fixture required");
            var w = EditorWindow.GetWindow(Type.GetType("UnityEditor.GameView,UnityEditor"));
            w.Focus();
            var settings = InputSystem.settings;
            if (AssetDatabase.Contains(settings))
                throw new Exception("Runtime settings only");
            string prior = JsonUtility.ToJson(settings);
            settings.editorInputBehaviorInPlayMode = InputSettings.EditorInputBehaviorInPlayMode.AllDeviceInputAlwaysGoesToGameView;
            settings.backgroundBehavior = InputSettings.BackgroundBehavior.IgnoreFocus;
            var kb = InputSystem.AddDevice<Keyboard>();
            kb.MakeCurrent();
            var b = new StringBuilder("UI navigation via synthetic keys/GameView clicks; letter seeded API in separate fixture profile.\n");
            var q = new Queue<Action>();
            Action<bool, string> check = (v, m) =>
            {
                b.AppendLine((v ? "PASS " : "FAIL ") + m);
                if (!v)
                    throw new Exception(m);
            };
            Action<Key> key = k => InputSystem.QueueStateEvent(kb, new KeyboardState(k));
            Action release = () => InputSystem.QueueStateEvent(kb, new KeyboardState());
            Action<float, float> click = (x, y) =>
            {
                var p = new Vector2(x * Screen.width / 1200f, y * Screen.height / 800f + 55);
                w.SendEvent(new Event{type = EventType.MouseDown, button = 0, mousePosition = p});
                w.SendEvent(new Event{type = EventType.MouseUp, button = 0, mousePosition = p});
            };
            Action<string> shot = n => ScreenCapture.CaptureScreenshot("Test/Output/CleanCheckout/" + n + ".png");
            q.Enqueue(() => click(285, 484));
            q.Enqueue(() =>
            {
                w.SendEvent(new Event{type = EventType.KeyDown, character = 'A', keyCode = KeyCode.A});
                w.SendEvent(new Event{type = EventType.KeyUp, keyCode = KeyCode.A});
            });
            q.Enqueue(() =>
            {
                check(s.data.mapping.Count == 1, "Cipher field accepts a typed letter through UI");
                shot("cipher-typed-1080");
            });
            q.Enqueue(() => click(130, 103));
            q.Enqueue(() => key(Key.P));
            q.Enqueue(() =>
            {
                release();
                check(s.Page == "dossier", "Back then P returns to dossier");
            });
            q.Enqueue(() => click(130, 182));
            q.Enqueue(() =>
            {
                check(s.Page == "compare", "Compare reached by dossier navigation");
                shot("compare-1080");
            });
            q.Enqueue(() => click(500, 180));
            q.Enqueue(() => click(950, 220));
            q.Enqueue(() => shot("compare-selected-1080"));
            q.Enqueue(() => click(130, 103));
            q.Enqueue(() => key(Key.P));
            q.Enqueue(() =>
            {
                release();
                check(s.Page == "dossier", "Dossier still reachable after compare");
            });
            q.Enqueue(() => click(700, 200));
            q.Enqueue(() =>
            {
                check(s.Page == "conclusions", "Conclusions reached from dossier main action");
                shot("conclusions-1080");
            });
            double next = EditorApplication.timeSinceStartup + 1;
            EditorApplication.CallbackFunction f = null;
            Action finish = () =>
            {
                EditorApplication.update -= f;
                InputSystem.RemoveDevice(kb);
                JsonUtility.FromJsonOverwrite(prior, settings);
                File.WriteAllText("Test/Output/CleanCheckout/navigation-continuation-ui.txt", b.ToString());
            };
            f = () =>
            {
                if (EditorApplication.timeSinceStartup < next)
                    return;
                next = EditorApplication.timeSinceStartup + 1.4;
                try
                {
                    if (q.Count == 0)
                    {
                        finish();
                        return;
                    }

                    q.Dequeue()();
                }
                catch (Exception e)
                {
                    b.AppendLine(e.ToString());
                    finish();
                }
            };
            EditorApplication.update += f;
            r.Log("Queue isolated navigation assertions");
        }
    }
}

